import{_ as e,o,c as a,ag as i}from"./chunks/framework.D9ghT4bC.js";const h=JSON.parse('{"title":"Autoupdates","description":"","frontmatter":{},"headers":[],"relativePath":"Modders/Autoupdates.md","filePath":"Modders/Autoupdates.md"}'),r={name:"Modders/Autoupdates.md"};function s(u,t,l,n,p,d){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="autoupdates" tabindex="-1">Autoupdates <a class="header-anchor" href="#autoupdates" aria-label="Permalink to &quot;Autoupdates&quot;">​</a></h1><p>Unciv contains built-in capabilities for packing images and autoupdating uniques.</p><p>You can automate these updates by adding a GitHub Actions workflow to your repository.</p><ul><li>In your Github page go to &quot;actions&quot; tab</li><li>Suggested for this repo &gt; Simple workflow &gt; &quot;Configure&quot;</li><li>Copy the text of <a href="https://github.com/yairm210/Unciv-IV-mod/blob/master/.github/workflows/autoupdate.yml" target="_blank" rel="noreferrer">this file</a> (&quot;copy raw file&quot;) to the new file in your repo</li><li>Change the file name to &quot;autoupdate.yml&quot; at the top</li><li>&quot;Commit changes&quot; (green button, top-right) &gt; &quot;Commit changes&quot;</li></ul><p>On every commit, and once per day, it will:</p><ul><li>Try to shrink PNGs (this is lossless, the pixel data remains the same but the file takes less space)</li><li>Try to autoupdate deprecated uniques</li></ul><p>If there are changes, this will create a PR to your repo - <a href="https://github.com/yairm210/Unciv-IV-mod/pull/31" target="_blank" rel="noreferrer">here&#39;s an example</a> - which you can choose to accept</p><p>If you see that the autoupdate isn&#39;t 100% - in which case talk to me and we&#39;ll sort it out 🙂</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>If you get a <code>remote: Permission to &lt;...&gt;.git denied to github-actions[bot].</code> You need to:</p><ul><li>Open Settings &gt; Actions &gt; General</li><li>Under &quot;Workflow permissions&quot; select &quot;Read and write permissions&quot;, &quot;Allow GitHub Actions to create and approve pull requests&quot;</li></ul>',11)])])}const m=e(r,[["render",s]]);export{h as __pageData,m as default};
